
const { from, of, defer } = require("rxjs");

const {
    concatMap,
    toArray,
    map
} = require("rxjs/operators");

const { parseWorkflowGraph } = require("./graph-parser.service");
const { executeNode } = require("./node-execution.service");

// Execute parsed workflow nodes sequentially using RxJS
const executeWorkflow = (workflow) => {
    // Convert the workflow graph into execution order
    const orderedNodes = parseWorkflowGraph(workflow);

    // Store output generated by each node
    const nodeResults = new Map();

    return from(orderedNodes).pipe(
        concatMap((node) =>
            defer(() => {
                const inputData = node.inputNodeId
                    ? nodeResults.get(node.inputNodeId)
                    : undefined;

                // Execute the current node
                const output = executeNode(node, inputData);

                // Save output for the next connected node
                nodeResults.set(node.id, output);

                return of({
                    nodeId: node.id,
                    output
                });
            })
        ),

        // Wait until every node has executed
        toArray(),

        // Prepare the final workflow execution result
        map((executions) => {
            const results = Object.fromEntries(
                executions.map((item) => [
                    item.nodeId,
                    item.output
                ])
            );

            return {
                success: true,
                executionOrder: executions.map(
                    (item) => item.nodeId
                ),
                nodeResults: results,
                finalOutput: executions.length > 0
                    ? executions[executions.length - 1].output
                    : null
            };
        })
    );
};

module.exports = {
    executeWorkflow
};
